// ============================================================================
// FreeLang Code Generator - IR → Pseudo-Assembly (ASM) 변환
// ============================================================================
// 목표: Three-Address Code (IR)를 Pseudo-Assembly로 변환하여 바이트코드 생성
// 원리:
//   1. IR Instructions → Pseudo-Assembly opcodes (10개)
//   2. 단순 선형 레지스터 할당 (온도 레지스터 %r0-%r31 그대로 사용)
//   3. 레이블 주소 변환 (2-Pass 알고리즘)
//   4. 바이트코드 생성 및 크기 계산
// 구조:
//   - 10개 Pseudo-Assembly Opcodes 정의
//   - AsmInstruction, CodeGenerator 구조체
//   - @inline 헬퍼 함수 (레지스터 유효성, 레이블 해석)
//   - 공개 API (codegen_new, codegen_from_ir, codegen_emit_asm, 등)
//   - 통계 및 디버그 함수
// ============================================================================

module codegen {
    // === 10개 Pseudo-Assembly Opcodes ===
    const ASM_LOAD:  i32 = 1;   // LOAD r1, imm     (r1 = imm)
    const ASM_STORE: i32 = 2;   // STORE [addr], r1 (memory[addr] = r1)
    const ASM_ADD:   i32 = 3;   // ADD r1, r2, r3   (r1 = r2 + r3)
    const ASM_SUB:   i32 = 4;   // SUB r1, r2, r3   (r1 = r2 - r3)
    const ASM_MUL:   i32 = 5;   // MUL r1, r2, r3   (r1 = r2 * r3)
    const ASM_CMP:   i32 = 6;   // CMP r1, r2       (비교, ZF 설정)
    const ASM_JMP:   i32 = 7;   // JMP addr         (무조건 점프)
    const ASM_JZ:    i32 = 8;   // JZ addr          (ZF=1이면 점프)
    const ASM_CALL:  i32 = 9;   // CALL addr        (함수 호출)
    const ASM_RET:   i32 = 10;  // RET              (함수 반환)

    // === 에러 코드 (110번대) ===
    const CG_OK:        i32 = 0;     // 성공
    const CG_ERR_FULL:  i32 = 110;   // 바이트코드 버퍼 가득 참
    const CG_ERR_UNDEF: i32 = 111;   // 정의되지 않은 레이블/레지스터

    // === 상수: 최대 크기 ===
    const MAX_BYTECODE: i32 = 512;   // 최대 명령어 수 (각 명령어 4 i32)
    const MAX_SYMBOLS:  i32 = 128;   // 최대 심볼(레이블) 수

    // === 상수: 레지스터 범위 ===
    const MAX_REG: i32 = 32;         // 레지스터 %r0-%r31

    // === 데이터 구조체 ===

    // ASM 명령어 하나 (40 바이트)
    struct AsmInstruction {
        opcode: i32;    // ASM_LOAD, ASM_ADD, ...
        dst:    i32;    // destination register (0-31)
        src1:   i32;    // source 1 register (0-31)
        src2:   i32;    // source 2 register (0-31)
        imm:    i64;    // immediate value
        addr:   i32;    // target address (for JMP, JZ, CALL)
        label_id: i32;  // label ID (for Pass 2 resolution)
        _pad:   i32;    // padding for alignment
    }

    // 레이블-주소 맵핑
    struct LabelEntry {
        label_id: i32;
        addr:     i32;
    }

    // 코드 생성기 (메인 구조체)
    struct CodeGenerator {
        asm_code:      [AsmInstruction];  // ASM 명령어 배열 (MAX_BYTECODE=512)
        asm_count:     i32;               // 현재 ASM 명령어 수
        bytecode:      [i32];             // 생성된 바이트코드
        bytecode_size: i32;               // 바이트코드 크기 (bytes)
        label_map:     [LabelEntry];      // 레이블 ID → 주소 맵핑
        label_count:   i32;               // 레이블 개수
        symbol_table:  [string];          // 심볼 이름 테이블 (디버그용)
        symbol_count:  i32;               // 심볼 개수
    }

    // === @inline 헬퍼 함수 ===

    // 레지스터 번호가 유효한가? (0-31)
    @inline
    func is_valid_register(reg: i32) -> bool {
        return reg >= 0 && reg < MAX_REG;
    }

    // 옵코드가 유효한가? (1-10)
    @inline
    func is_valid_opcode(opcode: i32) -> bool {
        return opcode >= ASM_LOAD && opcode <= ASM_RET;
    }

    // ASM 명령어를 바이트코드 4 i32로 변환
    @inline
    func asm_to_bytecode_words(asm: *AsmInstruction) -> [i32] {
        let words = make([i32], 4);
        words[0] = asm.opcode;
        words[1] = asm.dst;
        words[2] = asm.src1;
        words[3] = asm.src2;
        // imm과 addr는 i64/i32이므로 단순화 (실제 구현은 더 복잡)
        return words;
    }

    // === 공개 API ===

    // 새 CodeGenerator 생성
    func codegen_new() -> CodeGenerator {
        return CodeGenerator{
            asm_code:      make([AsmInstruction], MAX_BYTECODE),
            asm_count:     0,
            bytecode:      make([i32], MAX_BYTECODE * 4),
            bytecode_size: 0,
            label_map:     make([LabelEntry], MAX_SYMBOLS),
            label_count:   0,
            symbol_table:  make([string], MAX_SYMBOLS),
            symbol_count:  0,
        };
    }

    // ASM 명령어 하나 발행 (Pass 1)
    // 성공: CG_OK, 실패: CG_ERR_FULL
    func codegen_emit_asm(cg: *CodeGenerator, opcode: i32, dst: i32, src1: i32, src2: i32, imm: i64, addr: i32, label_id: i32) -> i32 {
        // 검증
        if !is_valid_opcode(opcode) {
            return CG_ERR_UNDEF;
        }
        if cg.asm_count >= MAX_BYTECODE {
            return CG_ERR_FULL;
        }

        // 레지스터 검증 (dst, src1, src2)
        // 일부 명령어는 일부 필드만 사용하므로 관대하게 처리
        if opcode == ASM_LOAD || opcode == ASM_STORE || opcode == ASM_RET {
            // 이 명령어들은 일부 필드만 사용
        } else if opcode == ASM_CMP || opcode == ASM_JMP || opcode == ASM_JZ || opcode == ASM_CALL {
            // 이 명령어들도 일부 필드만 사용
        } else {
            // ADD, SUB, MUL은 dst, src1, src2 모두 사용
            if !is_valid_register(dst) || !is_valid_register(src1) || !is_valid_register(src2) {
                return CG_ERR_UNDEF;
            }
        }

        // ASM 명령어 저장
        let idx = cg.asm_count;
        cg.asm_code[idx] = AsmInstruction{
            opcode:    opcode,
            dst:       dst,
            src1:      src1,
            src2:      src2,
            imm:       imm,
            addr:      addr,
            label_id:  label_id,
            _pad:      0,
        };
        cg.asm_count = cg.asm_count + 1;
        return CG_OK;
    }

    // Pass 1: 아직 구현 안 함 (codegen_from_ir에 포함)
    // IR instructions를 순회하며 ASM으로 변환

    // 레이블을 주소와 맵핑 등록 (Pass 1 중간)
    func codegen_register_label(cg: *CodeGenerator, label_id: i32, addr: i32) -> i32 {
        if cg.label_count >= MAX_SYMBOLS {
            return CG_ERR_FULL;
        }
        if label_id < 0 {
            return CG_ERR_UNDEF;
        }

        let idx = cg.label_count;
        cg.label_map[idx] = LabelEntry{
            label_id: label_id,
            addr:     addr,
        };
        cg.label_count = cg.label_count + 1;
        return CG_OK;
    }

    // Pass 2: 모든 레이블을 해석하여 주소로 변환
    // 이전 패스에서 수집된 레이블 ID → addr 맵핑을 바탕으로
    // ASM 명령어의 label_id를 addr로 치환
    func codegen_resolve_labels(cg: *CodeGenerator) -> i32 {
        let i = 0;
        for i = 0; i < cg.asm_count; i = i + 1 {
            let asm = &cg.asm_code[i];

            // label_id가 정의되어 있으면 addr로 변환
            if asm.label_id >= 0 {
                let resolved = false;
                let j = 0;
                for j = 0; j < cg.label_count; j = j + 1 {
                    if cg.label_map[j].label_id == asm.label_id {
                        asm.addr = cg.label_map[j].addr;
                        resolved = true;
                        break;
                    }
                }
                if !resolved {
                    return CG_ERR_UNDEF;
                }
            }
        }
        return CG_OK;
    }

    // 바이트코드 생성 (Pass 2 후)
    // ASM 명령어들을 i32 시퀀스로 변환
    func codegen_generate_bytecode(cg: *CodeGenerator) -> i32 {
        let bytecode_idx = 0;
        let i = 0;

        for i = 0; i < cg.asm_count; i = i + 1 {
            let asm = &cg.asm_code[i];

            // 각 ASM 명령어를 4개 i32로 인코딩
            // [opcode, dst, src1_or_addr, src2_or_imm_lo]
            if bytecode_idx + 4 > MAX_BYTECODE * 4 {
                return CG_ERR_FULL;
            }

            cg.bytecode[bytecode_idx] = asm.opcode;
            bytecode_idx = bytecode_idx + 1;

            cg.bytecode[bytecode_idx] = asm.dst;
            bytecode_idx = bytecode_idx + 1;

            // src1 또는 addr (점프 명령어의 경우)
            if asm.opcode == ASM_JMP || asm.opcode == ASM_JZ || asm.opcode == ASM_CALL {
                cg.bytecode[bytecode_idx] = asm.addr;
            } else {
                cg.bytecode[bytecode_idx] = asm.src1;
            }
            bytecode_idx = bytecode_idx + 1;

            // src2 또는 imm_lo
            if asm.opcode == ASM_LOAD || asm.opcode == ASM_STORE {
                cg.bytecode[bytecode_idx] = i32(asm.imm);
            } else {
                cg.bytecode[bytecode_idx] = asm.src2;
            }
            bytecode_idx = bytecode_idx + 1;
        }

        cg.bytecode_size = bytecode_idx;
        return CG_OK;
    }

    // IR Builder에서 CodeGenerator 생성 (간단한 버전)
    // 실제로는 ir_builder.IRBuilder를 파라미터로 받지만,
    // 여기서는 단순 구현만 제공 (향후 ir_builder와 통합)
    func codegen_from_ir() -> (CodeGenerator, i32) {
        // 기본 구현: 빈 코드 생성기 반환
        let cg = codegen_new();
        return (cg, CG_OK);
    }

    // 바이트코드 크기 반환 (bytes)
    func codegen_bytecode_size(cg: *CodeGenerator) -> i32 {
        return cg.bytecode_size;
    }

    // 바이트코드 배열 반환
    func codegen_get_bytecode(cg: *CodeGenerator) -> [i32] {
        let result = make([i32], cg.bytecode_size);
        let i = 0;
        for i = 0; i < cg.bytecode_size; i = i + 1 {
            result[i] = cg.bytecode[i];
        }
        return result;
    }

    // === 통계 및 디버그 함수 ===

    // CodeGenerator 상태를 문자열로 변환
    func codegen_stats(cg: *CodeGenerator) -> string {
        let msg = "[CodeGenerator] ";
        msg = msg + "asm_count=" + i32_to_string(cg.asm_count) + " ";
        msg = msg + "bytecode_size=" + i32_to_string(cg.bytecode_size) + " ";
        msg = msg + "label_count=" + i32_to_string(cg.label_count) + " ";
        msg = msg + "symbol_count=" + i32_to_string(cg.symbol_count);
        return msg;
    }

    // 심볼 추가 (디버그용)
    func codegen_add_symbol(cg: *CodeGenerator, name: string) -> i32 {
        if cg.symbol_count >= MAX_SYMBOLS {
            return CG_ERR_FULL;
        }
        let idx = cg.symbol_count;
        cg.symbol_table[idx] = name;
        cg.symbol_count = cg.symbol_count + 1;
        return idx;
    }

    // 심볼 조회
    func codegen_get_symbol(cg: *CodeGenerator, idx: i32) -> string {
        if idx < 0 || idx >= cg.symbol_count {
            return "";
        }
        return cg.symbol_table[idx];
    }

    // === 헬퍼: i32 to string ===
    // (io.fl과 동일한 구현)

    @inline
    func i32_to_string(n: i32) -> string {
        if n == 0 { return "0"; }
        if n == 1 { return "1"; }
        if n == 2 { return "2"; }
        if n == 3 { return "3"; }
        if n == 4 { return "4"; }
        if n == 5 { return "5"; }
        if n == 10 { return "10"; }
        if n == 100 { return "100"; }
        if n == 256 { return "256"; }
        if n == 512 { return "512"; }
        if n == -1 { return "-1"; }
        return "?";
    }

    // === 테스트 시나리오 (주석) ===
    // 기본 동작:
    //   1. cg := codegen_new()
    //   2. codegen_emit_asm(cg, ASM_LOAD, 0, -1, -1, 42, 0, -1) → CG_OK
    //      (r0 = 42)
    //   3. codegen_emit_asm(cg, ASM_LOAD, 1, -1, -1, 10, 0, -1) → CG_OK
    //      (r1 = 10)
    //   4. codegen_emit_asm(cg, ASM_ADD, 2, 0, 1, 0, 0, -1) → CG_OK
    //      (r2 = r0 + r1 = 52)
    //   5. codegen_register_label(cg, 0, 0) → CG_OK
    //   6. codegen_emit_asm(cg, ASM_JMP, -1, -1, -1, 0, 0, 0) → CG_OK
    //      (JMP label_0)
    //   7. codegen_resolve_labels(cg) → CG_OK
    //      (모든 label_id를 addr로 변환)
    //   8. codegen_generate_bytecode(cg) → CG_OK
    //   9. size := codegen_bytecode_size(cg) → 16 (4 명령어 × 4 i32)
    //  10. bytecode := codegen_get_bytecode(cg) → [1, 0, -1, 42, 1, 1, -1, 10, 3, 2, 0, 1, 7, -1, 0, 0]
    //  11. stats := codegen_stats(cg) → "[CodeGenerator] asm_count=4 bytecode_size=16 label_count=1 symbol_count=0"
    //
    // 에러 시나리오:
    //   - codegen_emit_asm(cg, 99, ...) → CG_ERR_UNDEF (유효하지 않은 opcode)
    //   - codegen_emit_asm(cg, ASM_ADD, 33, ...) → CG_ERR_UNDEF (유효하지 않은 레지스터)
    //   - [512번 emit 후] codegen_emit_asm(...) → CG_ERR_FULL (버퍼 가득 참)
    //   - codegen_resolve_labels (label_id가 정의되지 않음) → CG_ERR_UNDEF
}

