func test_codegen_basic() -> bool {
    let cg = codegen.codegen_new();

    // Test 1: ASM_LOAD 명령어 발행
    let err = codegen.codegen_emit_asm(&cg, codegen.ASM_LOAD, 0, -1, -1, 42, 0, -1);
    if err != codegen.CG_OK {
        return false;
    }
    if cg.asm_count != 1 {
        return false;
    }

    // Test 2: ASM_LOAD 또 다른 명령어
    err = codegen.codegen_emit_asm(&cg, codegen.ASM_LOAD, 1, -1, -1, 10, 0, -1);
    if err != codegen.CG_OK {
        return false;
    }
    if cg.asm_count != 2 {
        return false;
    }

    // Test 3: ASM_ADD 명령어
    err = codegen.codegen_emit_asm(&cg, codegen.ASM_ADD, 2, 0, 1, 0, 0, -1);
    if err != codegen.CG_OK {
        return false;
    }
    if cg.asm_count != 3 {
        return false;
    }

    // Test 4: 바이트코드 생성
    err = codegen.codegen_generate_bytecode(&cg);
    if err != codegen.CG_OK {
        return false;
    }

    // Test 5: 바이트코드 크기 확인 (3 명령어 × 4 i32 = 12)
    let size = codegen.codegen_bytecode_size(&cg);
    if size != 12 {
        return false;
    }

    return true;
}

func test_codegen_label_resolution() -> bool {
    let cg = codegen.codegen_new();

    // 레이블 0 등록 (주소 0)
    let err = codegen.codegen_register_label(&cg, 0, 0);
    if err != codegen.CG_OK {
        return false;
    }

    // JMP label_0 발행 (아직 label_id=0, addr=0으로 설정됨)
    err = codegen.codegen_emit_asm(&cg, codegen.ASM_JMP, -1, -1, -1, 0, 0, 0);
    if err != codegen.CG_OK {
        return false;
    }

    // Pass 2: 레이블 해석
    err = codegen.codegen_resolve_labels(&cg);
    if err != codegen.CG_OK {
        return false;
    }

