    if cg.asm_code[0].addr != 0 {
        return false;
    }

    return true;
}

func test_codegen_register_validation() -> bool {
    let cg = codegen.codegen_new();

    // 유효한 레지스터 (0-31)
    let err = codegen.codegen_emit_asm(&cg, codegen.ASM_ADD, 31, 0, 1, 0, 0, -1);
    if err != codegen.CG_OK {
        return false;
    }

    // 유효하지 않은 레지스터 (32)
    err = codegen.codegen_emit_asm(&cg, codegen.ASM_ADD, 32, 0, 1, 0, 0, -1);
    if err != codegen.CG_ERR_UNDEF {
        return false;
    }

    return true;
}

func test_codegen_opcode_validation() -> bool {
    let cg = codegen.codegen_new();

    // 유효하지 않은 opcode (11 > ASM_RET)
    let err = codegen.codegen_emit_asm(&cg, 11, 0, 0, 0, 0, 0, -1);
    if err != codegen.CG_ERR_UNDEF {
        return false;
    }

    return true;
}

func test_codegen_symbol_table() -> bool {
    let cg = codegen.codegen_new();

    // 심볼 추가
    let idx1 = codegen.codegen_add_symbol(&cg, "main");
    if idx1 != 0 {
        return false;
    }

    let idx2 = codegen.codegen_add_symbol(&cg, "loop");
    if idx2 != 1 {
        return false;
    }

    // 심볼 조회
    let sym1 = codegen.codegen_get_symbol(&cg, 0);
    if sym1 != "main" {
        return false;
    }

    let sym2 = codegen.codegen_get_symbol(&cg, 1);
    if sym2 != "loop" {
        return false;
    }

    return true;
}

// 모든 테스트 실행
func test_codegen_all() -> bool {
    if !test_codegen_basic() {
        return false;
    }
    if !test_codegen_label_resolution() {
        return false;
    }
    if !test_codegen_register_validation() {
        return false;
    }
    if !test_codegen_opcode_validation() {
        return false;
    }
    if !test_codegen_symbol_table() {
        return false;
    }
    return true;
}

