   102→
   103→    // 새 CodeGenerator 생성
   104→    func codegen_new() -> CodeGenerator {
   105→        return CodeGenerator{
   106→            asm_code:      make([AsmInstruction], MAX_BYTECODE),
   107→            asm_count:     0,
   108→            bytecode:      make([i32], MAX_BYTECODE * 4),
   109→            bytecode_size: 0,
   110→            label_map:     make([LabelEntry], MAX_SYMBOLS),
   111→            label_count:   0,
   112→            symbol_table:  make([string], MAX_SYMBOLS),
   113→            symbol_count:  0,
   114→        };
   115→    }
   116→
   117→    // ASM 명령어 하나 발행 (Pass 1)
   118→    // 성공: CG_OK, 실패: CG_ERR_FULL
   119→    func codegen_emit_asm(cg: *CodeGenerator, opcode: i32, dst: i32, src1: i32, src2: i32, imm: i64, addr: i32, label_id: i32) -> i32 {
   120→        // 검증
   121→        if !is_valid_opcode(opcode) {
   122→            return CG_ERR_UNDEF;
   123→        }
   124→        if cg.asm_count >= MAX_BYTECODE {
   125→            return CG_ERR_FULL;
   126→        }
   127→
   128→        // 레지스터 검증 (dst, src1, src2)
   129→        // 일부 명령어는 일부 필드만 사용하므로 관대하게 처리
   130→        if opcode == ASM_LOAD || opcode == ASM_STORE || opcode == ASM_RET {
   131→            // 이 명령어들은 일부 필드만 사용
   132→        } else if opcode == ASM_CMP || opcode == ASM_JMP || opcode == ASM_JZ || opcode == ASM_CALL {
   133→            // 이 명령어들도 일부 필드만 사용
   134→        } else {
   135→            // ADD, SUB, MUL은 dst, src1, src2 모두 사용
   136→            if !is_valid_register(dst) || !is_valid_register(src1) || !is_valid_register(src2) {
   137→                return CG_ERR_UNDEF;
   138→            }
   139→        }
   140→
   141→        // ASM 명령어 저장
   142→        let idx = cg.asm_count;
   143→        cg.asm_code[idx] = AsmInstruction{
   144→            opcode:    opcode,
   145→            dst:       dst,
   146→            src1:      src1,
   147→            src2:      src2,
   148→            imm:       imm,
   149→            addr:      addr,
   150→            label_id:  label_id,
   151→            _pad:      0,
   152→        };
   153→        cg.asm_count = cg.asm_count + 1;
   154→        return CG_OK;
   155→    }
