   157→    // Pass 1: 아직 구현 안 함 (codegen_from_ir에 포함)
   158→    // IR instructions를 순회하며 ASM으로 변환
   159→
   160→    // 레이블을 주소와 맵핑 등록 (Pass 1 중간)
   161→    func codegen_register_label(cg: *CodeGenerator, label_id: i32, addr: i32) -> i32 {
   162→        if cg.label_count >= MAX_SYMBOLS {
   163→            return CG_ERR_FULL;
   164→        }
   165→        if label_id < 0 {
   166→            return CG_ERR_UNDEF;
   167→        }
   168→
   169→        let idx = cg.label_count;
   170→        cg.label_map[idx] = LabelEntry{
   171→            label_id: label_id,
   172→            addr:     addr,
   173→        };
   174→        cg.label_count = cg.label_count + 1;
   175→        return CG_OK;
   176→    }
   177→
   178→    // Pass 2: 모든 레이블을 해석하여 주소로 변환
   179→    // 이전 패스에서 수집된 레이블 ID → addr 맵핑을 바탕으로
   180→    // ASM 명령어의 label_id를 addr로 치환
   181→    func codegen_resolve_labels(cg: *CodeGenerator) -> i32 {
   182→        let i = 0;
   183→        for i = 0; i < cg.asm_count; i = i + 1 {
   184→            let asm = &cg.asm_code[i];
   185→
   186→            // label_id가 정의되어 있으면 addr로 변환
   187→            if asm.label_id >= 0 {
   188→                let resolved = false;
   189→                let j = 0;
   190→                for j = 0; j < cg.label_count; j = j + 1 {
   191→                    if cg.label_map[j].label_id == asm.label_id {
   192→                        asm.addr = cg.label_map[j].addr;
   193→                        resolved = true;
   194→                        break;
   195→                    }
   196→                }
   197→                if !resolved {
   198→                    return CG_ERR_UNDEF;
   199→                }
   200→            }
   201→        }
   202→        return CG_OK;
   203→    }
   204→
   205→    // 바이트코드 생성 (Pass 2 후)
   206→    // ASM 명령어들을 i32 시퀀스로 변환
   207→    func codegen_generate_bytecode(cg: *CodeGenerator) -> i32 {
   208→        let bytecode_idx = 0;
   209→        let i = 0;
   210→
   211→        for i = 0; i < cg.asm_count; i = i + 1 {
   212→            let asm = &cg.asm_code[i];
   213→
   214→            // 각 ASM 명령어를 4개 i32로 인코딩
   215→            // [opcode, dst, src1_or_addr, src2_or_imm_lo]
   216→            if bytecode_idx + 4 > MAX_BYTECODE * 4 {
   217→                return CG_ERR_FULL;
   218→            }
   219→
   220→            cg.bytecode[bytecode_idx] = asm.opcode;
   221→            bytecode_idx = bytecode_idx + 1;
   222→
   223→            cg.bytecode[bytecode_idx] = asm.dst;
   224→            bytecode_idx = bytecode_idx + 1;
   225→
   226→            // src1 또는 addr (점프 명령어의 경우)
   227→            if asm.opcode == ASM_JMP || asm.opcode == ASM_JZ || asm.opcode == ASM_CALL {
   228→                cg.bytecode[bytecode_idx] = asm.addr;
   229→            } else {
   230→                cg.bytecode[bytecode_idx] = asm.src1;
   231→            }
   232→            bytecode_idx = bytecode_idx + 1;
   233→
   234→            // src2 또는 imm_lo
   235→            if asm.opcode == ASM_LOAD || asm.opcode == ASM_STORE {
   236→                cg.bytecode[bytecode_idx] = i32(asm.imm);
   237→            } else {
   238→                cg.bytecode[bytecode_idx] = asm.src2;
   239→            }
   240→            bytecode_idx = bytecode_idx + 1;
   241→        }
   242→
   243→        cg.bytecode_size = bytecode_idx;
   244→        return CG_OK;
   245→    }
